import base64
import requests

def upload_image(image_path, server_url):
    try:
        # Ler a imagem e codificar em base64
        with open(image_path, "rb") as image_file:
            encoded_image = base64.b64encode(image_file.read()).decode('utf-8')

        # Gravar a imagem codificada em um arquivo local (opcional)
        with open("encoded_image.txt", "w") as f:
            f.write(encoded_image)

        # Enviar a imagem codificada para o servidor remoto
        headers = {'Content-Type': 'application/json'}
        payload = {'image': encoded_image}
        response = requests.post(server_url, json=payload, headers=headers)

        # Verificar o status da requisição
        if response.status_code == 200:
            return "sucesso"
        else:
            return "falha"

    except Exception as e:
        print(f"Erro ao enviar a imagem: {e}")
        return "falha"
